package dev.jobflow.api; import jakarta.validation.*; import java.util.NoSuchElementException; import org.springframework.dao.*; import org.springframework.http.*; import org.springframework.security.access.AccessDeniedException; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*;
@RestControllerAdvice public class ApiExceptionHandler { @ExceptionHandler(NoSuchElementException.class) ResponseEntity<ApiError> notFound(Exception e){return ResponseEntity.status(404).body(ApiError.of(404,"NOT_FOUND",e.getMessage()));} @ExceptionHandler({IllegalArgumentException.class,IllegalStateException.class,ConstraintViolationException.class}) ResponseEntity<ApiError> bad(Exception e){return ResponseEntity.badRequest().body(ApiError.of(400,"INVALID_REQUEST",e.getMessage()));} @ExceptionHandler(dev.jobflow.service.RateLimitService.RateLimitExceededException.class) ResponseEntity<ApiError> rate(Exception e){return ResponseEntity.status(429).body(ApiError.of(429,"RATE_LIMITED",e.getMessage()));} @ExceptionHandler(AccessDeniedException.class) ResponseEntity<ApiError> forbidden(Exception e){return ResponseEntity.status(403).body(ApiError.of(403,"FORBIDDEN","Access denied"));} @ExceptionHandler(DataIntegrityViolationException.class) ResponseEntity<ApiError> conflict(Exception e){return ResponseEntity.status(409).body(ApiError.of(409,"CONFLICT","Conflicting resource state"));} @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<ApiError> validation(MethodArgumentNotValidException e){return ResponseEntity.badRequest().body(ApiError.of(400,"VALIDATION_ERROR",e.getBindingResult().getFieldError().getDefaultMessage()));} }
